         --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
         font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         background:
           radial-gradient(circle at top, rgba(79, 70, 229, 0.14), transparent 34%),
           linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
         color: var(--text);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface-strong);
         color: var(--text);
         transform: translateY(-160%);
         transition: transform 0.2s ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       main {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .panel {
         width: min(100%, 40rem);
         padding: clamp(1.5rem, 4vw, 2.5rem);
         border: 1px solid rgba(255, 255, 255, 0.7);
         border-radius: 1.5rem;
         background: var(--surface);
         box-shadow: var(--shadow);
         backdrop-filter: blur(16px);
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(1.9rem, 4vw, 2.5rem);
         line-height: 1.1;
       }

       .intro {
         margin: 0 0 1.75rem;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .required-note,
       .field-help,
       .field-message,
       .submission-message {
         margin: 0;
         line-height: 1.5;
       }

       .required-note,
       .field-help {
         color: var(--muted);
         font-size: 0.95rem;
       }

       .form-field {
         margin: 0;
         padding: 1.25rem;
         border: 1px solid var(--border);
         border-radius: 1.25rem;
         background: var(--surface-strong);
       }

       .form-field legend {
         padding: 0 0.375rem;
         font-size: 1.05rem;
         font-weight: 700;
       }

       .form-field[data-invalid="true"] {
         border-color: rgba(180, 35, 24, 0.4);
       }

       .radio-grid {
         display: grid;
         gap: 0.875rem;
         margin-top: 1rem;
       }

       .radio-option {
         display: block;
       }

       .radio-option input {
         position: absolute;
         opacity: 0.0001;
       }

       .option-content {
         display: flex;
         align-items: center;
         gap: 0.875rem;
         width: 100%;
         padding: 1rem 1.1rem;
         border: 1px solid var(--border);
         border-radius: 1rem;
         background: #fbfcff;
         transition:
           border-color 0.2s ease,
           background-color 0.2s ease,
           box-shadow 0.2s ease,
           transform 0.2s ease;
       }

       .option-content::before {
         content: "";
         width: 1.2rem;
         height: 1.2rem;
         border: 2px solid var(--border-strong);
         border-radius: 50%;
         flex: 0 0 auto;
         background: var(--surface-strong);
         box-shadow: inset 0 0 0 0.25rem transparent;
       }

       .radio-option input:checked + .option-content {
         border-color: var(--accent);
         background: var(--accent-soft);
         box-shadow: 0 12px 24px rgba(79, 70, 229, 0.12);
       }

       .radio-option input:checked + .option-content::before {
         border-color: var(--accent);
         box-shadow: inset 0 0 0 0.3rem var(--accent);
       }

       .radio-option input:focus-visible + .option-content {
         outline: 3px solid rgba(55, 48, 163, 0.28);
         outline-offset: 3px;
       }

       .radio-option input:hover + .option-content,
       .radio-option input:focus-visible + .option-content {
         border-color: var(--accent);
       }

       .option-title {
         font-weight: 600;
       }

       .field-message {
         margin-top: 0.875rem;
         color: var(--error);
         font-weight: 600;
       }

       .submission-message {
         min-height: 1.5rem;
         color: var(--success);
         font-weight: 600;
       }

       button[type="submit"] {
         justify-self: start;
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.4rem;
         background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
         color: #ffffff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 16px 28px rgba(79, 70, 229, 0.26);
       }

       button[type="submit"]:focus-visible {
         outline: 3px solid rgba(55, 48, 163, 0.28);
         outline-offset: 3px;
       }

       @media (max-width: 40rem) {
         .panel {
           border-radius: 1.2rem;
         }

         .form-field {
           padding: 1rem;
         }

         button[type="submit"] {
           width: 100%;
           justify-self: stretch;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           animation: none !important;
           transition: none !important;
           scroll-behavior: auto !important;
         }
       }

       @media (forced-colors: active) {
         .panel,
         .form-field,
         .option-content,
         button[type="submit"] {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .radio-option input:checked + .option-content,
         .radio-option input:focus-visible + .option-content,
         button[type="submit"]:focus-visible,
         .skip-link:focus {
           outline: 2px solid Highlight;
           outline-offset: 3px;
         }

         .option-content::before {
           border-color: CanvasText;
           background: Canvas;
         }
       }
