         <form id="preferences-form" novalidate>
           <p class="required-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

           <fieldset
             class="form-field"
             id="notification-field"
             aria-describedby="notification-help notification-error"
           >
             <legend>
               How do you prefer to receive notifications?
               <span aria-hidden="true">*</span>
             </legend>
             <p class="field-help" id="notification-help">Select one option.</p>

             <div class="radio-grid">
               <label class="radio-option">
                 <input
                   id="notification-email"
                   name="notificationPreference"
                   type="radio"
                   value="Email"
                   required
                 />
                 <span class="option-content">
                   <span class="option-title">Email</span>
                 </span>
               </label>

               <label class="radio-option">
                 <input
                   id="notification-sms"
                   name="notificationPreference"
                   type="radio"
                   value="SMS"
                   required
                 />
                 <span class="option-content">
                   <span class="option-title">SMS</span>
                 </span>
               </label>

               <label class="radio-option">
                 <input
                   id="notification-push"
                   name="notificationPreference"
                   type="radio"
                   value="Push Notifications"
                   required
                 />
                 <span class="option-content">
                   <span class="option-title">Push Notifications</span>
                 </span>
               </label>
             </div>

             <p class="field-message" id="notification-error" hidden></p>
           </fieldset>

           <button type="submit">Save preference</button>
           <p class="submission-message" id="submission-message" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("preferences-form");
       const notificationField = document.getElementById("notification-field");
       const errorMessage = document.getElementById("notification-error");
       const submissionMessage = document.getElementById("submission-message");
       const radios = Array.from(
         form.querySelectorAll('input[name="notificationPreference"]')
       );

       function showError(message) {
         notificationField.dataset.invalid = "true";
         errorMessage.textContent = message;
         errorMessage.hidden = false;
         submissionMessage.textContent = "";

         radios.forEach((radio) => {
           radio.setAttribute("aria-invalid", "true");
         });
       }

       function clearError() {
         delete notificationField.dataset.invalid;
         errorMessage.textContent = "";
         errorMessage.hidden = true;

         radios.forEach((radio) => {
           radio.removeAttribute("aria-invalid");
         });
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const selectedOption = form.querySelector(
           'input[name="notificationPreference"]:checked'
         );

         if (!selectedOption) {
           showError("Error: Select how you prefer to receive notifications.");
           radios[0].focus();
           return;
         }

         clearError();
         submissionMessage.textContent = `Preference saved: ${selectedOption.value}.`;
       });

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           clearError();
           submissionMessage.textContent = "";
         });
       });
     </script>
')

